// Minimal Cosmic Drift game
// Canvas element with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth;
  const height = canvas.height = canvas.clientHeight;

  // Ship state
  const ship = {
    x: width / 2,
    y: height / 2,
    angle: 0,
    vx: 0,
    vy: 0,
    radius: 10,
  };

  // Game objects
  const asteroids = [];
  const orbs = [];
  let score = 0;
  let gameOver = false;

  // Settings
  const ASTEROID_COUNT = 8;
  const ORB_SPAWN_INTERVAL = 5000; // ms
  const THRUST = 0.1;
  const ROT_SPEED = 0.07;
  const MAX_SPEED = 5;

  // Helpers
  const rand = (min, max) => Math.random() * (max - min) + min;
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);

  // Initialize asteroids
  for (let i = 0; i < ASTEROID_COUNT; i++) {
    asteroids.push({
      x: rand(0, width),
      y: rand(0, height),
      vx: rand(-1, 1),
      vy: rand(-1, 1),
      radius: rand(15, 30),
    });
  }

  // Input handling
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  // Orb spawning
  function spawnOrb() {
    orbs.push({
      x: rand(0, width),
      y: rand(0, height),
      radius: 6,
    });
  }
  setInterval(spawnOrb, ORB_SPAWN_INTERVAL);

  function update() {
    if (gameOver) return;
    // Ship controls
    if (keys.ArrowLeft) ship.angle -= ROT_SPEED;
    if (keys.ArrowRight) ship.angle += ROT_SPEED;
    if (keys.ArrowUp) {
      ship.vx += Math.cos(ship.angle) * THRUST;
      ship.vy += Math.sin(ship.angle) * THRUST;
    }
    // Clamp speed
    const speed = Math.hypot(ship.vx, ship.vy);
    if (speed > MAX_SPEED) {
      ship.vx *= MAX_SPEED / speed;
      ship.vy *= MAX_SPEED / speed;
    }
    // Move ship
    ship.x = (ship.x + ship.vx + width) % width;
    ship.y = (ship.y + ship.vy + height) % height;

    // Move asteroids
    for (const a of asteroids) {
      a.x = (a.x + a.vx + width) % width;
      a.y = (a.y + a.vy + height) % height;
    }

    // Collision ship‑asteroid
    for (const a of asteroids) {
      if (dist(ship, a) < ship.radius + a.radius) {
        gameOver = true;
        break;
      }
    }

    // Collision ship‑orb
    for (let i = orbs.length - 1; i >= 0; i--) {
      if (dist(ship, orbs[i]) < ship.radius + orbs[i].radius) {
        score++;
        orbs.splice(i, 1);
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Stars background (simple)
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, width, height);

    // Draw ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(12, 0);
    ctx.lineTo(-8, -6);
    ctx.lineTo(-8, 6);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Draw asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw orbs
    ctx.fillStyle = '#ff0';
    for (const o of orbs) {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '32px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
